namespace ghidra.framework.main.projectdata.actions;

using docking.action;
using ghidra.framework.main.datatable;
using ghidra.framework.main.datatable;
using ghidra.framework.main.datatree;
using ghidra.framework.model;
using ghidra.util;

public class ProjectDataReadOnlyAction : ProjectDataContextToggleAction {

	public ProjectDataReadOnlyAction(string owner, string group) : base("Read-Only", owner)
    {
		setPopupMenuData(new MenuData(new string[] { "Read-Only" }, group));
		setSelected(false);
		markHelpUnnecessary();
	}

	/* @Override */
	protected void actionPerformed(ProjectDataContext context) {
		DomainFile file = context.getSelectedFiles().get(0);
		toggleReadOnly(file);
		object contextObject = context.getContextObject();
		if (contextObject is DomainFileNode) {
			DomainFileNode node = (DomainFileNode) contextObject;
			node.fireNodeChanged();
		}
	}

	/* @Override */
	public bool isAddToPopup(ProjectDataContext context) {
		if (!context.isInActiveProject()) {
			return false;
		}
		if (context.getFolderCount() != 0 || context.getFileCount() != 1) {
			return false;
		}

		DomainFile domainFile = context.getSelectedFiles().get(0);
		setSelected(domainFile.isReadOnly());
		return true;
	}

	/* @Override */
	protected bool isEnabledForContext(ProjectDataContext context) {
		if (context.getFolderCount() != 0 || context.getFileCount() != 1) {
			return false;
		}
		DomainFile domainFile = context.getSelectedFiles().get(0);
		return !domainFile.isVersioned();
	}

	/**
	 * Toggle the read-only property on the domain file.
	 */
	private void toggleReadOnly(DomainFile file) {
		try {
			file.setReadOnly(!file.isReadOnly());
		}
		catch (Exception e) {
			Msg.showError(this, null, "Error setting read-only state for " + file.getName(),
				e.getMessage(), e);
		}
	}
}
